  if (!processReadMail && aMsgHdr.isRead) {
    return null;
  }
  if (inboxOnly && !isInbox) {
    return null;
  }
  if (selfSentOnly) {
    const sender = lazy.EnigmailFuncs.parseEmails(aMsgHdr.author, true);
    let id = null;
    if (sender && sender[0]) {
      id = getIdentityForSender(sender[0].email, aMsgHdr.folder.server);
    }

    if (!id) {
      return null;
    }
  }

  const uri = aMsgHdr.folder.getUriForMsg(aMsgHdr);
  const url = MailServices.messageServiceFromURI(uri).getUrlForUri(uri);
  const op = url.spec.indexOf("?") > 0 ? "&" : "?";
  return {
    url: url.spec + op + "header=enigmailFilter",
    requireBody,
  };
}
